import io
p='src/offering/entities/offeringPackage.entity.ts'
s=open(p).read()

# 1) imports
old_imp = "import { PaymentSchedule, aggregationMethod } from '../../dimensions/dto/create-dimension.dto.js';"
assert old_imp in s
new_imp = "import { PaymentSchedule, aggregationMethod, overageAllowedEnum } from '../../dimensions/dto/create-dimension.dto.js';\nimport { FreeDimensionOnInvoice } from '../../setting/dto/FreeDimensionOnInvoice.js';"
s=s.replace(old_imp,new_imp,1)

# 2) helpers after billableTotal
anchor = """    static billableTotal(usage: AggregatedUsageResponse['usage']): string {
        const total = (usage ?? []).reduce((acc, { value }) => {
            acc += parseFloat(value);
            return acc;
        }, 0);
        return total.toFixed(2).toString();
    }
"""
assert anchor in s
helpers = anchor + """
    /**
     * How much of a dimension's usage the customer actually owes for.
     *
     * A dimension without an allowance is owed for in full. When an allowance is
     * present only the usage which runs past it can be charged, and only when
     * running past it is permitted:
     *  - an unlimited (`inf`) allowance can never be exhausted, so nothing is owed,
     *  - an allowance the usage stays within leaves nothing owed,
     *  - an allowance the plan forbids overage on leaves nothing owed, however far
     *    past it the usage runs.
     */
    static chargeableUsage({
        total,
        usageEntitlement,
        overageAllowed,
    }: {
        total: number;
        usageEntitlement?: ReadDimensionResponseData['usageEntitlement'];
        overageAllowed?: ReadDimensionResponseData['overageAllowed'];
    }): number {
        const usageTotal = Number.isFinite(Number(total)) ? Number(total) : 0;
        if (usageEntitlement === undefined || usageEntitlement === null) {
            // No allowance to work through, every unit is owed for.
            return usageTotal;
        }
        if (usageEntitlement === 'inf') {
            // An unlimited allowance is never exhausted.
            return 0;
        }
        if (String(overageAllowed) !== String(overageAllowedEnum.true)) {
            // The plan does not permit usage beyond the allowance, so none of it is charged.
            return 0;
        }
        const allowance = Number(usageEntitlement);
        if (!Number.isFinite(allowance)) {
            return 0;
        }
        const overage = usageTotal - allowance;
        return overage > 0 ? overage : 0;
    }

    /**
     * Whether the plan prices this dimension at zero, which is what makes it a
     * free dimension as far as the invoice settings are concerned.
     */
    static dimensionIsPricedAtZero(dimension: ReadDimensionResponseData): boolean {
        const consumptionPrice = dimension?.consumptionPrice;
        if (consumptionPrice === undefined || consumptionPrice === null || `${consumptionPrice}`.trim() === '') {
            return false;
        }
        const price = parseFloat(consumptionPrice as unknown as string);
        return Number.isFinite(price) && price === 0;
    }

    /**
     * Whether a dimension earns a line on the invoice: it does when the customer
     * owes something on it, and it does when the plan prices it at zero unless the
     * business asked for free dimensions to be kept off the invoice.
     */
    static dimensionEarnsLineItem({
        dimension,
        chargeableTotal,
        unitCost,
        settings,
    }: {
        dimension: ReadDimensionResponseData;
        chargeableTotal: number;
        unitCost: number;
        settings?: ReadSettingsResponseData;
    }): boolean {
        if (Offering.dimensionIsPricedAtZero(dimension)) {
            return settings?.freeDimensionOnInvoice !== FreeDimensionOnInvoice.hide;
        }
        return chargeableTotal > 0 && Number.isFinite(unitCost) && unitCost !== 0;
    }
"""
s=s.replace(anchor, helpers, 1)

# 3) non tiered loop
old_loop = """            const {
                usageIncrement,
                consumptionUnit: { unit, type },
            } = nonTieredDimensionsMap[dimensionId];
