                negative,
            });
            lineItems.addLineItem(new InvoiceLineItem(displayName, displayTotal, unitCost));
        });"""
assert old_loop in s
new_loop = """            const {
                usageIncrement,
                consumptionUnit: { unit, type },
            } = nonTieredDimensionsMap[dimensionId];
            // Only the usage the customer owes for reaches the invoice, an allowance
            // which is unlimited, unexhausted, or which the plan forbids overage on
